    83  static inline int is_float(const char *buf, int len)
    84  {
    85      const char *end = buf + len;
    86      const char *p = buf;
    87
    88      while (p <= end) {
    89          if (*p == '.') {
    90              return 1;
    91          }
    92          p++;
    93      }
    94      return 0;
    95  }
