   211  /*
   212   * It parse a JSON string and convert it to MessagePack format, this packer is
   213   * useful when a complete JSON message exists, otherwise it will fail until
   214   * the message is complete.
   215   *
   216   * This routine do not keep a state in the parser, do not use it for big
   217   * JSON messages.
   218   */
   219  int flb_pack_json(const char *js, size_t len, char **buffer, size_t *size,
   220                    int *root_type)
   221
   222  {
   223      int ret = -1;
   224      int out;
   225      int last;
   226      char *buf = NULL;
   227      struct flb_pack_state state;
   228
   229      ret = flb_pack_state_init(&state);
   230      if (ret != 0) {
   231          return -1;
   232      }
   233      ret = flb_json_tokenise(js, len, &state);
   234      if (ret != 0) {
   235          ret = -1;
   236          goto flb_pack_json_end;
   237      }
   238
   239      if (state.tokens_count == 0) {
   240          ret = -1;
   241          goto flb_pack_json_end;
   242      }
   243
   244      buf = tokens_to_msgpack(&state, js, &out, &last);
   245      if (!buf) {
   246          ret = -1;
   247          goto flb_pack_json_end;
   248      }
   249
   250      *root_type = state.tokens[0].type;
   251      *size = out;
   252      *buffer = buf;
   253
   254      ret = 0;
   255
   256   flb_pack_json_end:
   257      flb_pack_state_reset(&state);
   258      return ret;
   259  }
