   261  /* Initialize a JSON packer state */
   262  int flb_pack_state_init(struct flb_pack_state *s)
   263  {
   264      int tokens = 256;
   265      size_t size = 256;
   266
   267      jsmn_init(&s->parser);
   268
   269      size = sizeof(jsmntok_t) * tokens;
   270      s->tokens = flb_calloc(1, size);
   271      if (!s->tokens) {
   272          flb_errno();
   273          return -1;
   274      }
   275      s->tokens_size   = tokens;
   276      s->tokens_count  = 0;
   277      s->last_byte     = 0;
   278      s->multiple      = FLB_FALSE;
   279
   280      s->buf_data = flb_malloc(size);
   281      if (!s->buf_data) {
   282          flb_errno();
   283          flb_free(s->tokens);
   284          return -1;
   285      }
   286      s->buf_size = size;
   287      s->buf_len = 0;
   288
   289      return 0;
   290  }
   291
   292  void flb_pack_state_reset(struct flb_pack_state *s)
   293  {
   294      flb_free(s->tokens);
   295      s->tokens_size  = 0;
   296      s->tokens_count = 0;
   297      s->last_byte    = 0;
   298      s->buf_size     = 0;
   299      flb_free(s->buf_data);
   300  }
